def minSwaps(nums: list[int]) -> int:
    arr = nums[:]
    i = 0
    j = len(arr) - 1
    swaps = 0
    while i < j:
        while i < j and arr[i] != 0:
            i += 1
        while i < j and arr[j] == 0:
            j -= 1
        if i < j:
            arr[i], arr[j] = arr[j], arr[i]
            swaps += 1
            i += 1
            j -= 1
    return swaps

#include <vector>
#include <algorithm>

class Solution {
public:
    int minSwaps(std::vector<int>& nums) {
        std::vector<int> arr = nums;
        int i = 0, j = (int)arr.size() - 1;
        int swaps = 0;
        while (i < j) {
            while (i < j && arr[i] != 0) i++;
            while (i < j && arr[j] == 0) j--;
            if (i < j) {
                std::swap(arr[i], arr[j]);
                swaps++;
                i++;
                j--;
            }
        }
        return swaps;
    }
};

class Solution {
    public int minSwaps(int[] nums) {
        int[] arr = nums.clone();
        int i = 0, j = arr.length - 1;
        int swaps = 0;
        while (i < j) {
            while (i < j && arr[i] != 0) i++;
            while (i < j && arr[j] == 0) j--;
            if (i < j) {
                int tmp = arr[i];
                arr[i] = arr[j];
                arr[j] = tmp;
                swaps++;
                i++;
                j--;
            }
        }
        return swaps;
    }
}

